import type {HandoffScope} from './cashier-handoff';
export type BankMatchRequest={id:string;account:string;deposit:string;statement:string;amount:string;reason:string};
const uuid=(v:unknown)=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
export function checkedBankMatch(v:BankMatchRequest):BankMatchRequest{if(!v||![v.id,v.account,v.deposit,v.statement].every(uuid)||typeof v.amount!=='string'||! /^[1-9][0-9]{0,11}$/.test(v.amount)||typeof v.reason!=='string'||v.reason!==v.reason.trim()||v.reason.length<4||v.reason.length>500||/[\x00-\x1f\x7f]/.test(v.reason))throw Error('Review the selected records, match amount and explanation.');return {id:v.id,account:v.account,deposit:v.deposit,statement:v.statement,amount:v.amount,reason:v.reason}}
export function bankMatchArgs(r:BankMatchRequest,scope:HandoffScope){checkedBankMatch(r);return {p_tenant:scope.tenant,p_property:scope.property,p_deposit:r.deposit,p_statement:r.statement,p_request:r.id,p_amount_minor:r.amount,p_reason:r.reason,p_confirmed:true}}
export function readBankMatchReceipt(value:unknown,r:BankMatchRequest,scope:HandoffScope,status=false){let v=value as Record<string,unknown>;const scoped=(x:Record<string,unknown>)=>x&&x.schema_version===1&&x.tenant_id===scope.tenant&&x.property_id===scope.property&&x.actor_id===scope.actor;if(status){if(!scoped(v)||v.kind!=='match'||v.request_id!==r.id||typeof v.found!=='boolean')throw Error('Match recovery scope changed.');if(!v.found){if(v.result!==null)throw Error('Invalid match recovery.');return false}v=v.result as Record<string,unknown>}if(!scoped(v)||v.match_id!==r.id||v.account_id!==r.account||v.deposit_id!==r.deposit||v.statement_id!==r.statement||v.amount_minor!==r.amount||v.reason!==r.reason||v.source!=='manual'||v.bank_verified!==false||v.journal_posted!==false||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Match receipt does not match the request.');return true}
